 const vm=require('node:vm'),P={state:{mode:'play'},Maps:{selected:'campo'},$:()=>({setAttribute(){}})},param=()=>({value:0,setTargetAtTime(v){this.value=v}});class AC{constructor(){this.currentTime=1;this.state='running';this.sampleRate=100;this.destination={}}createGain(){return {gain:param(),connect(){}}}createBuffer(){return {getChannelData(){return new Float32Array(100)}}}}
