test('Alternancia musical: fundido, pausa, reutilización, errores y cambio de opción',async()=>{
 const vm=require('node:vm'),elements=new Map(),created=[],storage=new Map();let live=true;
 const P={$:id=>{if(!elements.has(id))elements.set(id,{value:'',textContent:''});return elements.get(id)},Audio:{unlock(){P.BackgroundMusic.gesture()},sync(){P.BackgroundMusic.sync(live)}}};
 class Media{constructor(){this.paused=true;this.currentTime=0;this.duration=100;this.readyState=4;this.events={};created.push(this)}addEventListener(k,f){this.events[k]=f}play(){this.paused=false;return Promise.resolve()}pause(){this.paused=true}removeAttribute(){this.src=''}load(){this.currentTime=0}}
 vm.runInNewContext(fs.readFileSync(path.join(root,'src/systems/background-music.js'),'utf8'),{P,Audio:Media,Promise,Math,Number,localStorage:{getItem:k=>storage.get(k)??null,setItem:(k,v)=>storage.set(k,v)},document:{addEventListener(){}}});
 const b=P.BackgroundMusic;b.init();assert.equal(b.choice,'alternate');assert.equal(created.length,0);b.sync(false);assert.equal(created.length,0);b.sync(true);await Promise.resolve();const first=b.player;assert.equal(b.loaded,'tema1');first.currentTime=87;b.sync(true);assert.equal(created.length,1,'No precargar demasiado pronto');first.currentTime=88;b.sync(true);const second=b.nextPlayer;assert.equal(created.length,2);assert(second.paused);assert.equal(second.volume,0);assert.equal(second.preload,'auto');first.currentTime=97;second.readyState=2;b.sync(true);assert(!b.fading,'Esperar datos de la siguiente pista');assert(!first.paused);second.readyState=4;b.sync(true);await Promise.resolve();assert(b.fading);assert(!second.paused);second.currentTime=1.5;b.sync(true);assert(Math.abs(first.volume-b.volume/Math.sqrt(2))<1e-10);assert(Math.abs(second.volume-first.volume)<1e-10);const clock=second.currentTime;b.sync(false);assert(first.paused&&second.paused);b.sync(false);assert.equal(second.currentTime,clock);b.sync(true);await Promise.resolve();assert(!first.paused&&!second.paused);assert.equal(second.currentTime,clock,'Reanudar sin reiniciar fundido');P.$('#music-volume').value=20;P.$('#music-volume').oninput();assert(Math.abs(second.volume-.2/Math.sqrt(2))<1e-10);second.currentTime=3;b.sync(true);assert.equal(b.player,second);assert.equal(b.loaded,'tema2');assert(first.paused);assert.equal(first.src,'');assert.equal(b.player.volume,.2);
 second.currentTime=97;b.sync(true);assert.equal(created.length,2,'Reutilizar el reproductor liberado');assert.equal(b.nextPlayer,first);assert.match(first.src,/tema-1/);await Promise.resolve();first.currentTime=3;b.sync(true);assert.equal(b.loaded,'tema1');assert.equal(b.player,first);first.currentTime=97;b.sync(true);await Promise.resolve();second.events.error();assert.equal(b.nextPlayer,null);assert.equal(b.player,first);assert(!b.useSynth(),'Error de precarga conserva pista actual');assert.equal(first.volume,.2);b.sync(true);assert.equal(b.nextPlayer,null,'No repetir descargas fallidas cada fotograma');b.gesture();b.sync(true);assert(b.nextPlayer);const select=P.$('#background-music');select.value='none';select.onchange();await Promise.resolve();assert(first.paused&&second.paused);assert.equal(b.nextPlayer,null);assert.equal(storage.get('perusurvivor-music'),'none');assert(!b.useSynth());
});
test('Música opcional: carga diferida, un reproductor, pausa, volumen, persistencia y errores',async()=>{
 const vm=require('node:vm'),elements=new Map(),storage=new Map([['perusurvivor-music','none']]),listeners={},created=[];let live=false,deny=false;
 const P={$:id=>{if(!elements.has(id))elements.set(id,{textContent:'',value:''});return elements.get(id)},Audio:{unlock(){P.BackgroundMusic.gesture()},sync(){P.BackgroundMusic.sync(live)}}};
 class Media{constructor(){this.paused=true;this.events={};this.plays=0;created.push(this)}addEventListener(k,fn){this.events[k]=fn}play(){this.plays++;if(deny)return Promise.reject(Error('NotAllowedError'));this.paused=false;return Promise.resolve()}pause(){this.paused=true}removeAttribute(){this.src=''}load(){}}
 vm.runInNewContext(fs.readFileSync(path.join(root,'src/systems/background-music.js'),'utf8'),{P,Audio:Media,Promise,Number,Math,localStorage:{getItem:k=>storage.get(k)??null,setItem:(k,v)=>storage.set(k,v)},document:{hidden:false,addEventListener:(k,fn)=>listeners[k]=fn}});
 const b=P.BackgroundMusic;b.init();assert.equal(b.choice,'none','Respetar la preferencia guardada');assert.equal(created.length,0);const select=P.$('#background-music');select.value='tema1';select.onchange();assert.equal(created.length,0,'No descargar pistas en menú');live=true;P.Audio.sync();await Promise.resolve();assert.equal(created.length,1);const player=b.player;assert.equal(player.preload,'none');assert(player.loop);assert.match(player.src,/tema-1-v1.webm$/);assert.equal(player.volume,.35);for(let i=0;i<120;i++)b.sync(true);assert.equal(player.plays,1,'No recrear ni reiniciar cada fotograma');b.sync(false);assert(player.paused);b.sync(true);await Promise.resolve();assert(!player.paused);P.$('#music-volume').value=20;P.$('#music-volume').oninput();assert.equal(player.volume,.2);assert.equal(storage.get('perusurvivor-music'),'tema1');select.value='tema2';select.onchange();await Promise.resolve();assert.equal(created.length,1);assert.match(player.src,/tema-2-v1.webm$/);select.value='none';select.onchange();assert(player.paused);assert(!b.useSynth());select.value='original';select.onchange();assert(b.useSynth());assert(player.paused);
 select.value='tema1';select.onchange();b.pause();await Promise.resolve();assert(player.paused,'Una promesa tardía no continúa tras pausar');deny=true;b.sync(true);await Promise.resolve();await Promise.resolve();const plays=player.plays;b.sync(true);assert.equal(player.plays,plays,'No reintentar autoplay bloqueado cada fotograma');deny=false;b.gesture();b.sync(true);await Promise.resolve();player.events.error();assert(b.useSynth(),'Error de pista recupera música original');assert(player.paused);assert.match(P.$('#music-status').textContent,/original/);
});
