test('Ambiente sonoro: cercanía, dos fuentes reutilizadas, pausa y prioridad de efectos',()=>{
 const vm=require('node:vm'),sources=[],notes=[];const param=()=>({value:0,calls:[],setTargetAtTime(v){this.value=v;this.calls.push(v)}});function context(){return {state:'running',currentTime:0,sampleRate:100,createBuffer(){return {getChannelData(){return new Float32Array(200)}}},createBufferSource(){const source={playbackRate:{value:1},connect(){},disconnect(){},start(){this.started=true},stop(){this.stopped=true}};sources.push(source);return source},createBiquadFilter(){return {frequency:param(),Q:{value:0},connect(){},disconnect(){}}},createGain(){return {gain:param(),connect(){},disconnect(){}}}}}const P={Audio:{ctx:null,master:{},voices:0,tone(...args){notes.push(args)}},Maps:{selected:'plaza',current(){return {fountain:{x:0,y:0}}}},state:{mapTime:0,player:{x:0,y:0}}};vm.runInNewContext(fs.readFileSync(path.join(root,'src/systems/soundscape.js'),'utf8'),{P});const a=P.Soundscape;a.tick(true);assert.equal(sources.length,0,'Ningún contexto propio ni autoplay');const c=context();P.Audio.ctx=c;a.tick(true);assert.equal(sources.length,2);assert(a.nodes[1].gain.gain.value>0);const near=a.profile('plaza',0,{x:0,y:0},{x:0,y:0}).water,far=a.profile('plaza',0,{x:600,y:0},{x:0,y:0}).water;assert(near>0);assert.equal(far,0);for(let i=0;i<120;i++){c.currentTime+=1/60;a.tick(true)}assert.equal(sources.length,2);assert(a.nodes[0].gain.gain.calls.length<25,'Control a 10 Hz');a.tick(false);assert(a.nodes.every(n=>n.gain.gain.value===0));P.Maps.selected='campo';c.currentTime+=1;a.tick(true);P.state.mapTime=7;c.currentTime+=1;a.tick(true);assert.equal(notes.length,2);c.currentTime+=1;a.tick(true);assert.equal(notes.length,2,'No acumular trinos');P.Audio.voices=9;P.state.mapTime=a.nextBird;c.currentTime+=1;a.tick(true);assert.equal(notes.length,2,'Prioridad al combate');P.state.bossSpawned=true;c.currentTime+=1;a.tick(true);assert(a.nodes.every(n=>n.gain.gain.value===0));P.state.bossSpawned=false;const next=context();P.Audio.ctx=next;a.tick(true);assert.equal(sources.length,4);assert(sources.slice(0,2).every(s=>s.stopped));a.dispose();assert.equal(a.nodes,null);
});

